# flake.nix
{
  description = "JAIDE V35: Root-Level Non-Transformer Polyglot LLM with FMRN Architecture";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";
    flake-utils.url = "github:numtide/flake-utils";
    zig-overlay.url = "github:mitchellh/zig-overlay";
    clash-nix.url = "github:clash-lang/clash-nix";
    rust-overlay.url = "github:oxalica/rust-overlay";
    julia.url = "github:NixOS/nixpkgs/nixos-unstable";
    julia.flake = false;
    sbt-derivation.url = "github:zaninime/sbt-derivation";
    sbt-derivation.inputs.nixpkgs.follows = "nixpkgs";
    openjdk.url = "github:NixOS/nixpkgs/nixos-unstable";
    openjdk.flake = false;
    elixir.url = "github:NixOS/nixpkgs/nixos-unstable";
    elixir.flake = false;
    ponyc.url = "github:NixOS/nixpkgs/nixos-unstable";
    ponyc.flake = false;
    nim.url = "github:NixOS/nixpkgs/nixos-unstable";
    nim.flake = false;
    crystal.url = "github:NixOS/nixpkgs/nixos-unstable";
    crystal.flake = false;
    chapel.url = "github:NixOS/nixpkgs/nixos-unstable";
    chapel.flake = false;
    futhark.url = "github:NixOS/nixpkgs/nixos-unstable";
    futhark.flake = false;
    vale.url = "github:NixOS/nixpkgs/nixos-unstable";
    vale.flake = false;
    gleam.url = "github:NixOS/nixpkgs/nixos-unstable";
    gleam.flake = false;
    lean4.url = "github:NixOS/nixpkgs/nixos-unstable";
    lean4.flake = false;
    agda.url = "github:NixOS/nixpkgs/nixos-unstable";
    agda.flake = false;
    isabelle.url = "github:NixOS/nixpkgs/nixos-unstable";
    isabelle.flake = false;
    tlaplus.url = "github:NixOS/nixpkgs/nixos-unstable";
    tlaplus.flake = false;
    spin.url = "github:NixOS/nixpkgs/nixos-unstable";
    spin.flake = false;
    uppaal.url = "github:NixOS/nixpkgs/nixos-unstable";
    uppaal.flake = false;
    kframework.url = "github:kframework/k";
    kframework.flake = false;
    dedukti.url = "github:NixOS/nixpkgs/nixos-unstable";
    dedukti.flake = false;
    circom.url = "github:iden3/circom";
    circom.flake = false;
    yosys.url = "github:NixOS/nixpkgs/nixos-unstable";
    yosys.flake = false;
    nextpnr.url = "github:NixOS/nixpkgs/nixos-unstable";
    nextpnr.flake = false;
    swi-prolog.url = "github:NixOS/nixpkgs/nixos-unstable";
    swi-prolog.flake = false;
    filc.url = "github:NixOS/nixpkgs/nixos-unstable";
    filc.flake = false;
    tile-lang.url = "github:NixOS/nixpkgs/nixos-unstable";
    tile-lang.flake = false;
    unison.url = "github:NixOS/nixpkgs/nixos-unstable";
    unison.flake = false;
    racket.url = "github:NixOS/nixpkgs/nixos-unstable";
    racket.flake = false;
    raylib.url = "github:NixOS/nixpkgs/nixos-unstable";
    raylib.flake = false;
    python311Packages.url = "github:NixOS/nixpkgs/nixos-unstable";
    python311Packages.flake = false;
    qiskit.url = "github:NixOS/nixpkgs/nixos-unstable";
    qiskit.flake = false;
  };

  outputs = { self, nixpkgs, flake-utils, zig-overlay, clash-nix, rust-overlay, ... }@inputs:
    flake-utils.lib.eachDefaultSystem (system:
      let
        overlays = [
          zig-overlay.overlays.default
          rust-overlay.overlays.default
          (final: prev: {
            julia-bin = prev.julia-bin.override { enableGC = true; };
            clash-ghc = clash-nix.packages.${system}.clash-ghc;
            sbt = prev.sbt.withSource;
            yosys = prev.yosys;
            nextpnr-ecp5 = prev.nextpnrPackages.nextpnr-ecp5;
            ecppack = prev.ecppack;
            swipl = prev.swiProlog;
            filc = prev.python3Packages.buildPythonPackage rec {
              pname = "filc";
              version = "0.1.0";
              src = inputs.filc;
              doCheck = false;
            };
            tile = prev.python3Packages.buildPythonPackage rec {
              pname = "tile-lang";
              version = "0.1.0";
              src = inputs.tile-lang;
              doCheck = false;
            };
            gleam = prev.gleam;
            lean4 = prev.lean4;
            agda = prev.agda.withPackages (ps: [ ps.standard-library ]);
            isabelle = prev.isabelle;
            tlaplus = prev.tla-plus-bin-nix;
            spin = prev.spin;
            uppaal = prev.stdenv.mkDerivation {
              name = "uppaal-dummy";
              buildPhase = "true";
              installPhase = ''
                mkdir -p $out/bin
                cat > $out/bin/verifyta <<EOF
#!/bin/sh
echo "UPPAAL verification stub"
exit 0
EOF
                chmod +x $out/bin/verifyta
              '';
            };
            kframework = prev.kframework;
            dedukti = prev.dedukti;
            circom = prev.circom;
            ponyc = prev.ponyc;
            nim = prev.nim;
            crystal = prev.crystal;
            chapel = prev.chapel;
            futhark = prev.futhark;
            vale = prev.stdenv.mkDerivation {
              name = "vale-lang";
              buildPhase = "true";
              installPhase = ''
                mkdir -p $out/bin
                echo '#!/bin/sh' > $out/bin/vale
                echo 'echo "Vale stub"' >> $out/bin/vale
                chmod +x $out/bin/vale
              '';
            };
            python3 = prev.python311;
            qiskit-env = prev.python311.withPackages (ps: with ps; [ qiskit qiskit-aer numpy scipy matplotlib ]);
          })
        ];
        pkgs = import nixpkgs {
          inherit system overlays;
        };
        zig = pkgs.zig_0_12;
        julia = pkgs.julia-bin;
        clash = pkgs.clash-ghc;
        sbt = pkgs.sbt;
        yosys = pkgs.yosys;
        nextpnr = pkgs.nextpnr-ecp5;
        ecppack = pkgs.ecppack;
        swipl = pkgs.swiProlog;
        lean = pkgs.lean4;
        agda = pkgs.agda;
        isabelle = pkgs.isabelle;
        tlc = pkgs.tla-plus-bin-nix.tlc;
        spin = pkgs.spin;
        verifyta = pkgs.uppaal;
        kore = pkgs.kframework;
        dedukti = pkgs.dedukti;
        elixir = pkgs.elixir_1_15;
        ponyc = pkgs.ponyc;
        nim = pkgs.nim;
        crystal = pkgs.crystal;
        chpl = pkgs.chapel;
        futhark = pkgs.futhark;
        gleam = pkgs.gleam;
        python = pkgs.qiskit-env;
        circom = pkgs.circom;
        jaide-dev-shell = pkgs.mkShell {
          buildInputs = with pkgs; [
            zig
            julia
            elixir
            ponyc
            nim
            crystal
            chpl
            futhark
            gleam
            clash
            sbt
            yosys
            nextpnr
            ecppack
            swipl
            lean
            agda
            isabelle
            tlc
            spin
            verifyta
            kore
            dedukti
            circom
            python
            (writeScriptBin "jaide-build" ''
              #!${pkgs.bash}/bin/bash
              source ${pkgs.stdenv}/setup
              bash ${./build.sh}
            '')
          ];
          shellHook = ''
            export JAIDE_ROOT=$PWD
            export LD_LIBRARY_PATH=$LD_LIBRARY_PATH:$JAIDE_ROOT/build/lib
            echo "JAIDE V35 development shell loaded."
            echo "Available commands: jaide-build, zig, julia, elixir, etc."
          '';
        };
        jaide-package = pkgs.stdenv.mkDerivation rec {
          pname = "jaide-v35";
          version = "35.0.0";
          src = ./.;
          buildInputs = with pkgs; [
            zig
            julia
            elixir
            ponyc
            nim
            crystal
            chpl
            futhark
            gleam
            clash
            sbt
            yosys
            nextpnr
            ecppack
            swipl
            lean
            agda
            isabelle
            tlc
            spin
            verifyta
            kore
            dedukti
            circom
            python
          ];
          buildPhase = ''
            bash build.sh
          '';
          installPhase = ''
            mkdir -p $out/bin $out/lib $out/share/jaide
            cp -r build/* $out/share/jaide/
            cat > $out/bin/jaide-run << EOF
            #!${pkgs.bash}/bin/bash
            cd $out/share/jaide
            LD_LIBRARY_PATH=\$LD_LIBRARY_PATH:$out/share/jaide/lib ./bin/parallel_orchestrator
            EOF
            chmod +x $out/bin/jaide-run
          '';
          meta = {
            description = "JAIDE V35 Full Build";
            license = pkgs.lib.licenses.mit;
          };
        };
      in rec {
        packages.default = jaide-package;
        devShells.default = jaide-dev-shell;
        apps.jaide-run = flake-utils.lib.mkApp { drv = jaide-package; };
        checks.build = jaide-package;
        hydraJobs.build = jaide-package;
      }
    );
}

